      &lt;img class=&quot;img-lightbox&quot; alt=&quot;Eric Swalwell (D-CA) and Tony Gonzales (R-TX)&quot; loading=&quot;lazy&quot; decoding=&quot;async&quot; style=&quot;--img-width:200&quot; src=&quot;/images/SbJf2cYHN0-200.webp&quot; width=&quot;800&quot; height=&quot;511&quot; srcset=&quot;/images/SbJf2cYHN0-200.webp 200w, /images/SbJf2cYHN0-800.webp 800w&quot; sizes=&quot;200px&quot;&gt;
